    implementation 'org.tensorflow:tensorflow-lite:2.13.0'
    implementation 'org.tensorflow:tensorflow-lite-gpu:2.13.0'  // GPU delegate
}

// Kotlin code
import org.tensorflow.lite.Interpreter
import org.tensorflow.lite.gpu.GpuDelegate
import android.content.res.AssetManager
import java.nio.ByteBuffer
import java.nio.ByteOrder

class TFLiteModel(assetManager: AssetManager, modelPath: String) {
    private val interpreter: Interpreter

    init {
        // Load model
        val model = loadModelFile(assetManager, modelPath)

        // Options (GPU delegate)
        val options = Interpreter.Options()
        val gpuDelegate = GpuDelegate()
        options.addDelegate(gpuDelegate)
        options.setNumThreads(4)

        interpreter = Interpreter(model, options)

        println("Model loaded: ${interpreter.inputTensorCount} inputs, ${interpreter.outputTensorCount} outputs")
    }

    private fun loadModelFile(assetManager: AssetManager, modelPath: String): ByteBuffer {
        val fileDescriptor = assetManager.openFd(modelPath)
        val inputStream = fileDescriptor.createInputStream()
        val fileChannel = inputStream.channel
        val startOffset = fileDescriptor.startOffset
        val declaredLength = fileDescriptor.declaredLength
        return fileChannel.map(java.nio.channels.FileChannel.MapMode.READ_ONLY, startOffset, declaredLength)
    }

    fun predict(inputBuffer: ByteBuffer): FloatArray {
        // Output
        val output = Array(1) { FloatArray(10) }  // 10 classes

        // Inference
        interpreter.run(inputBuffer, output)

        return output[0]
    }

    fun close() {
        interpreter.close()
    }
}

